import{_ as o,o as c,c as d,a5 as p}from"./chunks/framework.DJo0M80U.js";const v=JSON.parse('{"title":"介绍","description":"","frontmatter":{"title":"介绍","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","构建运维","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第七部分：构建与运维/01-Maven/介绍.md","filePath":"posts/java快速入门/第七部分：构建与运维/01-Maven/介绍.md"}'),a={name:"posts/java快速入门/第七部分：构建与运维/01-Maven/介绍.md"};function r(t,e,n,s,i,l){return c(),d("div",null,[...e[0]||(e[0]=[p('<div><p><strong>什么是</strong></p><ul><li>Maven</li><li>Maven</li></ul><p>的正确发音是<code>[</code>ˈ<code>mev</code>ə<code>n]</code>，而不是“马瘟”以及其他什么瘟。<code>Maven</code> 在美国是一个口语化的词 语，代表专家、内行的意思。</p><p>一个对</p><p><code>Maven</code></p><p>比较正式的定义是这么说的：<code>Maven</code> 是一个项目管理工具，它包含了一个<strong>项目对象模</strong><strong>型</strong></p><p><code>(POM</code></p><p>：</p><p><code>Project Object Model)</code></p><p>，一组标准集合，一个项目生命周期<code>(Project Lifecycle)</code>，一个依赖管理系统<code>(Dependency Management System)</code>，和用来运行定义在生命周期阶段<code>(phase)</code>中插件<code>(plugin)</code>目标<code>(goal)</code>的逻辑。</p><p><code>Maven</code> <strong>能解决什么问题</strong> 可以用更通俗的方式来说明。我们知道，项目开发不仅仅是写写代码而已，期间会伴随着各种必不可少的事情要做，下面列举几个感受一下： 在<a href="https://baike.baidu.com/item/%E8%BD%AF%E4%BB%B6" target="_blank" rel="noreferrer">软件</a>领域，<code>JAR</code><strong>文件</strong>（<code>Java</code>归档，英语：</p><ul><li>Java</li><li>Archive</li></ul><p>）是一种<a href="https://baike.baidu.com/item/%E8%BD%AF%E4%BB%B6%E5%8C%85" target="_blank" rel="noreferrer">软件包</a><a href="https://baike.baidu.com/item/%E6%96%87%E4%BB%B6%E6%A0%BC%E5%BC%8F" target="_blank" rel="noreferrer">文件格式</a>，通常用于聚合大量的<code>Java</code>类文件、相关的<a href="https://baike.baidu.com/item/%E5%85%83%E6%95%B0%E6%8D%AE" target="_blank" rel="noreferrer">元数据</a>和资源（文本、图片等）文件到一个文件，以便开发<code>Java</code>平台<a href="https://baike.baidu.com/item/%E5%BA%94%E7%94%A8%E8%BD%AF%E4%BB%B6" target="_blank" rel="noreferrer">应用软件</a>或<a href="https://baike.baidu.com/item/%E5%BA%93" target="_blank" rel="noreferrer">库</a>。 <code>JAR</code>文件是一种归档文件，以</p><p><code>ZIP</code></p><p>格式构建，以<code>.jar</code>为<a href="https://baike.baidu.com/item/%E6%96%87%E4%BB%B6%E6%89%A9%E5%B1%95%E5%90%8D" target="_blank" rel="noreferrer">文件扩展名</a>。用户可以使用</p><p><code>JDK</code></p><p>自带的<code>jar</code>命令创建或提取<code>JAR</code>文件。也可以使用其他<code>zip</code>压缩工具，不过压缩时<code>zip</code>文件头里的条目顺序很重要，因为<code>Manifest</code>文件常需放在首位。<code>JAR</code>文件内的文件名是<code>Unicode</code>文本。</p><p><code>1</code>、我们需要引用各种<code>jar</code>包，尤其是比较大的工程，引用的 <code>jar</code> 包往往有几十个乃至上百个， 每用 到一种</p><p><code>jar</code></p><p>包，都需要手动引入工程目录，而且经常遇到各种让人抓狂的 <code>jar</code> 包冲突，版本冲突。</p><p><code>2</code></p><p>、我们辛辛苦苦写好了 <code>Java</code> 文件，可是只懂 <code>0</code> 和 <code>1</code> 的白痴电脑却完全读不懂，需要将它编译成二 进制字节码。好歹现在这项工作可以由各种集成开发工具帮我们完成，<code>Eclipse</code>、<code>IDEA</code> 等都可以将代 码即时编译。当然，如果你嫌生命漫长，何不铺张，也可以用记事本来敲代码，然后用</p><p><code>javac</code></p><p>命令一 个个地去编译，逗电脑玩。</p><p><code>3</code></p><p>、世界上没有不存在<code>bug</code>的代码，计算机喜欢<code>bug</code>就和人们总是喜欢美女帅哥一样。为了追求美为 了减少</p><p><code>bug</code></p><p>，因此写完了代码，我们还要写一些单元测试，然后一个个的运行来检验代码质量。</p><p><code>4</code></p><p>、再优雅的代码也是要出来卖的。我们后面还需要把代码与各种配置文件、资源整合到一起，定型 打包，如果是</p><p><code>web</code></p><p>项目，还需要将之发布到服务器，供人蹂躏。 试想，如果现在有一种工具，可以把你从上面的繁琐工作中解放出来，能帮你构建工程，管理</p><p><code>jar</code> 包，编译代码，还能帮你自动运行单元测试，打包，生成报表，甚至能帮你部署项目，生成</p><p><code>Web</code></p><p>站 点，你会心动吗？<code>Maven</code> 就可以解决上面所提到的这些问题。</p><p><code>Maven</code></p><p><strong>的优势举例</strong> 前面我们通过<code>Web</code>阶段项目，要能够将项目运行起来，就必须将该项目所依赖的一些<code>jar</code>包添加到 工程中，否则项目就不能运行。试想如果具有相同架构的项目有十个，那么我们就需要将这一份</p><p><code>jar</code> 包复制到十个不同的工程中。我们一起来看一个</p><p><code>CRM</code></p><p>项目的工程大小。 使用传统</p><p><code>Web</code></p><p>项目构建的 <code>CRM</code> 项目如下：</p><p>原因主要是因为上面的</p><p><code>WEB</code></p><p>程序要运行，我们必须将项目运行所需的 <code>Jar</code> 包复制到工程目录中而导致了工程很大。同样的项目，如果我们使用 <code>Maven</code> 工程来构建，会发现总体上工程的大小会少很多。如下图<code>:</code></p><p>小结：可以初步推断它里面一定没有</p><p><code>jar</code></p><p>包，继续思考，没有 <code>jar</code> 包的项目怎么可能运行呢？</p><p><code>Maven</code> <strong>的两个精典作用</strong></p><p><code>Maven</code> <strong>的依赖管理</strong></p><p><code>Maven</code></p><p>的一个核心特性就是依赖管理。当我们涉及到多模块的项目（包含成百个模块或者子项目），管理依赖就变成一项困难的任务。<code>Maven</code> 展示出了它对处理这种情形的高度控制。</p><p>传统的</p><p><code>WEB</code></p><p>项目中，我们必须将工程所依赖的<code>jar</code>包复制到工程中，导致了工程的变得很大。那么</p><p><code>maven</code></p><p>工程是如何使得工程变得很少呢？</p><p>分析如下： 通过分析发现：<code>maven</code> 工程中不直接将 <code>jar</code> 包导入到工程中，而是通过在 <code>pom.xml</code> 文件中添加所需 <code>jar</code> 包的坐标，这样就很好的避免了</p><p><code>jar</code></p><p>直接引入进来，在需要用到 <code>jar</code> 包的时候，只要查找 <code>pom.xml</code> 文 件，再通过</p><p><code>pom.xml</code></p><p>文件中的坐标，到一个专门用于”存放 <code>jar</code> 包的仓库”<code>(maven</code> 仓库<code>)</code>中根据坐标从 而找到这些</p><p><code>jar</code></p><p>包，再把这些 <code>jar</code> 包拿去运行。</p><p>那么问题来了 第一：”存放 <code>jar</code> 包的仓库”长什么样？ 第二：通过读取</p><p><code>pom.xml</code></p><p>文件中的坐标，再到仓库中找到 <code>jar</code> 包，会不会很慢？从而导致这种方式 不可行！</p><p>第一个问题：存放</p><p><code>jar</code></p><p>包的仓库长什么样，这一点我们后期会分析仓库的分类，也会带大家去看我们 的本地的仓库长什么样。 第二个问题：通过</p><p><code>pom.xml</code></p><p>文件配置要引入的 <code>jar</code> 包的坐标，再读取坐标并到仓库中加载 <code>jar</code> 包，这 样我们就可以直接使用</p><p><code>jar</code></p><p>包了，为了解决这个过程中速度慢的问题，<code>maven</code> 中也有索引的概念，通 过建立索引，可以大大提高加载</p><p><code>jar</code></p><p>包的速度，使得我们认为 <code>jar</code> 包基本跟放在本地的工程文件中再 读取出来的速度是一样的。</p><p><strong>项目的一键构建</strong> 我们的项目，往往都要经历编译、测试、运行、打包、安装 ，部署等一系列过程。</p><p><strong>什么是构建？</strong> 指的是项目从编译、测试、运行、打包、安装 ，部署整个过程都交给</p><p><code>maven</code></p><p>进行管理，这个 过程称为构建。</p><p><strong>一键构建</strong> 指的是整个构建过程，使用</p><p><code>maven</code></p><p>一个命令可以轻松完成整个工作。</p><p><code>Maven</code> 规范化构建流程如下：</p><p>我们一起来看</p><p><code>Hello-Maven</code></p><p>工程的一键运行的过程。通过 <code>tomcat:run</code> 的这个命令，我们发现现在的 工程编译，测试，运行都变得非常简单。</p></div>',1)])])}const g=o(a,[["render",r]]);export{v as __pageData,g as default};
